'use client';
import {useEffect,useState} from 'react';
import {readFinancialPostingReview,type FinancialPostingSelection} from '@/lib/financial-migration-posting';
import {validateReconciliationRequest,type ReconciliationRequest,type ReconciliationDecision} from '@/lib/financial-reconciliation';
import {FinancialReconciliationSave} from './financial-reconciliation-save';
import {bankCloseMoney} from '@/lib/cashier-bank-close';
type Props={selection:FinancialPostingSelection;assessment:Record<string,unknown>;requestId:string;onSaved:(r:ReconciliationRequest)=>void;onCancelled?:()=>void;onRecoveryLock?:(locked:boolean)=>void};
export function FinancialReconciliationDecisions(props:Props){const s=props.selection;return <Decisions key={[s.scope.tenant,s.scope.property,s.scope.actor,s.batch].join(':')} {...props}/>}
function Decisions({selection,assessment,requestId,onSaved,onCancelled,onRecoveryLock}:Props){
 const review=readFinancialPostingReview(assessment.posting_review,selection);
 const [choices,setChoices]=useState<Record<string,{disposition:string;invoice:string;evidence:string}>>({}),[prepared,setPrepared]=useState<ReconciliationRequest|null>(null),[error,setError]=useState(''),[ready,setReady]=useState(false);
 const key=['irp.reconciliation.save.v1',selection.scope.tenant,selection.scope.property,selection.scope.actor,selection.batch].join(':');
 useEffect(()=>{try{const raw=sessionStorage.getItem(key);if(raw){const saved=JSON.parse(raw) as ReconciliationRequest;validateReconciliationRequest(saved);if(saved.selection.scope.tenant!==selection.scope.tenant||saved.selection.scope.property!==selection.scope.property||saved.selection.scope.actor!==selection.scope.actor||saved.selection.batch!==selection.batch)throw Error('Saved reconciliation belongs to another workspace.');setPrepared(saved)}setReady(true)}catch(e){setError(e instanceof Error?e.message:'Unable to restore reconciliation.')}},[key]);
 function change(source:string,field:string,value:string){setChoices(prev=>({...prev,[source]:{...(prev[source]??{disposition:'',invoice:'',evidence:''}),[field]:value}}));setError('')}
 function prepare(){try{const decisions:ReconciliationDecision[]=review.rows.map(row=>{const c=choices[row.source];return {source_item_id:row.source,disposition:c?.disposition as ReconciliationDecision['disposition'],invoice_id:c?.disposition==='existing_invoice'?c.invoice:null,evidence:c?.evidence??''}});const draft={id:requestId,selection,assessment,decisions};validateReconciliationRequest(draft);setPrepared(draft);setError('')}catch(e){setError(e instanceof Error?e.message:'Review every source item.')}}
 return <section className="card" aria-label="Reconcile source documents"><h3>Reconcile source documents</h3><p>Match original documents, not just equal amounts. Review prepayments and security separately from receivables.</p>{prepared?<FinancialReconciliationSave draft={prepared} onSaved={onSaved} onCancelled={onCancelled} onRecoveryLock={onRecoveryLock}/>:<><fieldset disabled={!ready}>{review.rows.map(row=>{const c=choices[row.source],raw=(review.raw.rows as Record<string,unknown>[]).find(r=>r.source_item_id===row.source),invoices=((raw?.destination_state as Record<string,unknown>)?.invoices??[]) as Record<string,unknown>[];return <div key={row.source}><h4>{row.source} · {row.reference}</h4><p>{row.category}: {bankCloseMoney(row.amount)}</p><label className="field">Decision for {row.source}<select value={c?.disposition??''} onChange={e=>change(row.source,'disposition',e.target.value)}><option value="">Choose after document review</option><option value="additional_balance">Additional balance not already represented</option>{row.category==='receivable'&&<option value="existing_invoice">Already represented by an existing invoice</option>}</select></label>{c?.disposition==='existing_invoice'&&<label className="field">Existing invoice for {row.source}<select value={c.invoice} onChange={e=>change(row.source,'invoice',e.target.value)}><option value="">Choose matching invoice</option>{invoices.filter(i=>i.reservation_id===row.reservation&&i.tenant_id===selection.scope.tenant&&i.property_id===selection.scope.property).map(i=><option key={String(i.id)} value={String(i.id)}>{String(i.invoice_number??i.id)}</option>)}</select></label>}<label className="field">Supporting reference for {row.source}<textarea maxLength={1000} value={c?.evidence??''} onChange={e=>change(row.source,'evidence',e.target.value)}/></label></div>})}</fieldset><button type="button" disabled={!ready} onClick={prepare}>Review reconciliation decisions</button></>}{error&&<p role="alert">{error}</p>}</section>;
}
